template <>
Result<void> validate<SignalSnapshot>(const SignalSnapshot& value) {
  (void)value;
  if (value.seat_position_mm > SignalSnapshot::seat_position_mm_max) {
    return make_error(ErrorCode::kOutOfRange, "SignalSnapshot.seat_position_mm out of range");
  }
  if (value.seat_recline_deg > SignalSnapshot::seat_recline_deg_max) {
    return make_error(ErrorCode::kOutOfRange, "SignalSnapshot.seat_recline_deg out of range");
  }
  if (!std::isfinite(value.hvac_setpoint_c) || value.hvac_setpoint_c < SignalSnapshot::hvac_setpoint_c_min || value.hvac_setpoint_c > SignalSnapshot::hvac_setpoint_c_max) {
    return make_error(ErrorCode::kOutOfRange, "SignalSnapshot.hvac_setpoint_c out of range");
  }
  if (value.hvac_fan_level > SignalSnapshot::hvac_fan_level_max) {
    return make_error(ErrorCode::kOutOfRange, "SignalSnapshot.hvac_fan_level out of range");
  }
  if (value.cabin_light_level > SignalSnapshot::cabin_light_level_max) {
    return make_error(ErrorCode::kOutOfRange, "SignalSnapshot.cabin_light_level out of range");
  }
  if (static_cast<unsigned>(value.cabin_light_color) > 2u) {
    return make_error(ErrorCode::kOutOfRange, "SignalSnapshot.cabin_light_color is not a valid LightColor");
  }
  if (static_cast<unsigned>(value.door_state) > 2u) {
    return make_error(ErrorCode::kOutOfRange, "SignalSnapshot.door_state is not a valid DoorState");
  }
  if (static_cast<unsigned>(value.ignition_state) > 2u) {
    return make_error(ErrorCode::kOutOfRange, "SignalSnapshot.ignition_state is not a valid IgnitionState");
  }
  return ok_status();
}

template <>
Result<Bytes> encode<SignalSnapshot>(const SignalSnapshot& value) {
  (void)value;
  auto status = validate(value);
  if (!status) return status.error();
  Bytes out;
  out.reserve(72);
  out.append_u16(value.seat_position_mm);
  out.append_u8(value.seat_recline_deg);
  out.append_f32(value.hvac_setpoint_c);
  out.append_u8(value.hvac_fan_level);
  out.append_u8(value.cabin_light_level);
  out.append_u8(static_cast<std::uint8_t>(value.cabin_light_color));
  out.append_u8(static_cast<std::uint8_t>(value.door_state));
  out.append_u8(static_cast<std::uint8_t>(value.ignition_state));
  out.append_u64(value.timestamp_us);
  return out;
}

template <>
Result<SignalSnapshot> decode<SignalSnapshot>(Bytes& in) {
  (void)in;
  SignalSnapshot value{};
  auto raw_seat_position_mm = in.read_u16();
  if (!raw_seat_position_mm) return raw_seat_position_mm.error();
  value.seat_position_mm = raw_seat_position_mm.value();
  auto raw_seat_recline_deg = in.read_u8();
  if (!raw_seat_recline_deg) return raw_seat_recline_deg.error();
  value.seat_recline_deg = raw_seat_recline_deg.value();
  auto raw_hvac_setpoint_c = in.read_f32();
  if (!raw_hvac_setpoint_c) return raw_hvac_setpoint_c.error();
  value.hvac_setpoint_c = raw_hvac_setpoint_c.value();
  auto raw_hvac_fan_level = in.read_u8();
  if (!raw_hvac_fan_level) return raw_hvac_fan_level.error();
  value.hvac_fan_level = raw_hvac_fan_level.value();
  auto raw_cabin_light_level = in.read_u8();
  if (!raw_cabin_light_level) return raw_cabin_light_level.error();
  value.cabin_light_level = raw_cabin_light_level.value();
  auto raw_cabin_light_color = in.read_u8();
  if (!raw_cabin_light_color) return raw_cabin_light_color.error();
  value.cabin_light_color = static_cast<LightColor>(raw_cabin_light_color.value());
  auto raw_door_state = in.read_u8();
  if (!raw_door_state) return raw_door_state.error();
  value.door_state = static_cast<DoorState>(raw_door_state.value());
  auto raw_ignition_state = in.read_u8();
  if (!raw_ignition_state) return raw_ignition_state.error();
  value.ignition_state = static_cast<IgnitionState>(raw_ignition_state.value());
  auto raw_timestamp_us = in.read_u64();
  if (!raw_timestamp_us) return raw_timestamp_us.error();
  value.timestamp_us = raw_timestamp_us.value();
  auto status = validate(value);
  if (!status) return status.error();
  return value;
}

template <>
Result<SignalSnapshot> decode<SignalSnapshot>(const Bytes& in) {
  Bytes copy = in;
  return decode<SignalSnapshot>(copy);
}

template <>
Result<void> validate<GetProfileResponse>(const GetProfileResponse& value) {
  (void)value;
  { auto nested = validate(value.profile); if (!nested) return nested.error(); }
  return ok_status();
}

template <>
Result<Bytes> encode<GetProfileResponse>(const GetProfileResponse& value) {
  (void)value;
  auto status = validate(value);
  if (!status) return status.error();
  Bytes out;
  out.reserve(16);
  out.append_u8(value.found ? 1u : 0u);
  { auto encoded = encode(value.profile);
    if (!encoded) return encoded.error();
    if (encoded.value().size() > 0xFFFFu)
      return make_error(ErrorCode::kOutOfRange, "GetProfileResponse.profile nested value too large");
    out.append_u16(static_cast<std::uint16_t>(encoded.value().size()));
    out.append_bytes(encoded.value()); }
  return out;
}

template <>
Result<GetProfileResponse> decode<GetProfileResponse>(Bytes& in) {
  (void)in;
  GetProfileResponse value{};
  auto raw_found = in.read_u8();
  if (!raw_found) return raw_found.error();
  value.found = raw_found.value() != 0;
  auto length = in.read_u16();
  if (!length) return length.error();
  auto nested_bytes = in.read_bytes(length.value());
  if (!nested_bytes) return nested_bytes.error();
  auto nested = decode<Profile>(nested_bytes.value());
  if (!nested) return nested.error();
  value.profile = nested.value();
  auto status = validate(value);
  if (!status) return status.error();
  return value;
}

template <>
Result<GetProfileResponse> decode<GetProfileResponse>(const Bytes& in) {
  Bytes copy = in;
  return decode<GetProfileResponse>(copy);
}

